-- Generated by build_world_batch.py. See its docstring and each
-- region's notes; style.json holds every claim's sources.

begin;

insert into public.wine_regions
  (region_code, name, aliases, country_code, latitude, longitude, radius_km,
   summary, red_body, red_acidity, red_tannin, pairing, label_note,
   source_url, publication_status)
values
  ('wr_0134', 'Sta. Rita Hills', '{"Santa Rita Hills"}'::text[], 'US', 34.635, -120.329, 7,
   'A cool AVA in western Santa Barbara County, where hills running east to west let Pacific fog and wind reach the vines. About two thirds of the vineyard is Pinot Noir, followed by Chardonnay.',
   null, null, null, null, 'Under federal rules, at least 85% of the wine must come from grapes grown in the AVA named on the label, and the wine must be finished in the state, or one of the states, where the AVA lies.',
   'https://www.staritahills.com/about', 'published'),
  ('wr_0135', 'Santa Maria Valley', '{}'::text[], 'US', 34.924, -120.306, 12,
   'A funnel shaped valley opening west to the Pacific, where morning fog and afternoon wind keep it cool and the growing season long. Pinot Noir and Chardonnay lead, with some Syrah, and the grapes keep plenty of acidity.',
   null, null, null, null, 'Under federal rules, at least 85% of the wine must come from grapes grown in the AVA named on the label, and the wine must be finished in the state, or one of the states, where the AVA lies.',
   'https://en.wikipedia.org/wiki/Santa_Maria_Valley_AVA', 'published'),
  ('wr_0136', 'Russian River Valley', '{}'::text[], 'US', 38.468, -122.862, 15,
   'A cool Sonoma County valley that begins about 10 miles from the Pacific, where morning fog and a wide swing between day and night keep acidity in the grapes. Chardonnay and Pinot Noir make up over 70% of the harvest.',
   null, null, null, null, 'Under federal rules, at least 85% of the wine must come from grapes grown in the AVA named on the label, and the wine must be finished in the state, or one of the states, where the AVA lies.',
   'https://russianrivervalley.org/about/climate/', 'published'),
  ('wr_0137', 'Columbia Valley', '{}'::text[], 'US', 46.754, -119.725, 123,
   'Washington''s largest AVA, a dry basin in the rain shadow of the Cascades that holds over 99% of the state''s vineyards. Warm days and cool nights on loess over flood deposits give ripe fruit while keeping natural acidity.',
   null, null, null, null, 'Under federal rules, at least 85% of the wine must come from grapes grown in the AVA named on the label, and the wine must be finished in the state, or one of the states, where the AVA lies.',
   'https://www.washingtonwine.org/resource/columbia-valley-ava/', 'published'),
  ('wr_0138', 'Walla Walla Valley', '{}'::text[], 'US', 46.022, -118.465, 21,
   'A valley shared by Washington and Oregon at the foot of the Blue Mountains, cooler and wetter than much of Washington, with loess over flood deposits and basalt cobbles in the south. Cabernet Sauvignon, Syrah and Merlot lead.',
   null, null, null, null, 'Under federal rules, at least 85% of the wine must come from grapes grown in the AVA named on the label, and the wine must be finished in the state, or one of the states, where the AVA lies.',
   'https://www.washingtonwine.org/resource/walla-walla-valley-ava/', 'published'),
  ('wr_0139', 'Santa Cruz Mountains', '{}'::text[], 'US', 37.236, -122.185, 24,
   'A cool mountain AVA between the Pacific and San Francisco Bay, the first in California defined by its mountain topography, much of it above the fog line. Plantings are split about evenly among Pinot Noir, Cabernet Sauvignon and Chardonnay.',
   null, null, null, null, 'Under federal rules, at least 85% of the wine must come from grapes grown in the AVA named on the label, and the wine must be finished in the state, or one of the states, where the AVA lies.',
   'https://winesofthesantacruzmountains.com/about', 'published'),
  ('wr_0140', 'Long Island', '{}'::text[], 'US', 40.885, -72.997, 35,
   'An AVA covering Nassau and Suffolk counties, where the Atlantic, Long Island Sound and Peconic Bay temper the climate over sandy glacial soils. Merlot is the most planted grape, and the wines tend to be restrained and crisp.',
   null, 4, null, null, 'Under federal rules, at least 85% of the wine must come from grapes grown in the AVA named on the label, and the wine must be finished in New York.',
   'https://liwines.com/about/', 'published'),
  ('wr_0141', 'Niagara Peninsula', '{}'::text[], 'CA', 43.151, -79.394, 30,
   'Canada''s largest viticultural area, on the south shore of Lake Ontario and crossed by the Niagara Escarpment, whose slopes and lake breezes shape the climate. Riesling, Chardonnay and Cabernet Franc lead, and Icewine is mostly made from Vidal.',
   null, null, null, null, 'A VQA wine naming Niagara Peninsula needs at least 85% of its grapes from there, all from Ontario, and vinifera grapes only, except Vidal for Icewine. Icewine grapes must freeze on the vine and be picked at minus 8°C or colder.',
   'https://vqaontario.ca/appellations/niagara-peninsula/', 'published'),
  ('wr_0142', 'Okanagan Valley', '{}'::text[], 'CA', 49.847, -119.519, 30,
   'British Columbia''s largest wine region, running over 250 km from the US border to Armstrong along Okanagan Lake. Summers are hot and dry with cool nights; the cooler north suits aromatic whites and the hot south bold reds.',
   4, null, null, null, 'A BC VQA wine may name Okanagan Valley when at least 85% of its grapes come from it and the rest from elsewhere in British Columbia.',
   'https://bcvqa.ca/geo_indication/okanagan-valley/', 'published'),
  ('wr_0143', 'Vale dos Vinhedos', '{"DO Vale dos Vinhedos"}'::text[], 'BR', -29.186, -51.559, 5,
   'A small valley in the Serra Gaúcha hills by Bento Gonçalves, and the first protected wine origin in Brazil. Merlot leads its reds and Chardonnay its whites, and sparkling wine is made here too.',
   null, null, null, null, 'Red blends must be led by Merlot, with only Cabernet Sauvignon, Cabernet Franc or Tannat beside it. White wines must contain Chardonnay, blended only with Riesling Itálico.',
   'https://www.gov.br/inpi/pt-br/servicos/indicacoes-geograficas/arquivos/status-pedidos/LISTADASINDICAESDEPROCEDNCIARECONHECIDAS.At27Outubro2026.pdf', 'published'),
  ('wr_0144', 'Campanha Gaúcha', '{"Campanha"}'::text[], 'BR', -30.781, -55.482, 30,
   'A wide stretch of Pampa grassland in the far south of Brazil, on the borders with Uruguay and Argentina. Warmer and drier than the Serra Gaúcha, it grows Chardonnay, Cabernet Sauvignon, Tannat and Merlot.',
   null, null, null, null, 'Wines under the IP must come wholly from grapes grown in the delimited area. A wine naming a grape or a vintage must be at least 85% that grape or vintage.',
   'https://www.gov.br/agricultura/pt-br/assuntos/sustentabilidade/indicacao-geografica/arquivos-publicacoes-ig/livreto-vinho.pdf', 'published'),
  ('wr_0145', 'Vale do São Francisco', '{}'::text[], 'BR', -9.079, -40.999, 90,
   'The tropical wine region of Brazil, on irrigated land along the São Francisco river in the semi-arid north east. Vines can crop twice a year, for sparkling wines, sweet Moscatel sparkling, Syrah reds and Chenin Blanc whites.',
   null, null, null, null, null,
   'https://www.gov.br/inpi/pt-br/servicos/indicacoes-geograficas/arquivos/fichas-tecnicas-de-indicacoes-geograficas/ValedoSoFrancisco.pdf', 'published'),
  ('wr_0146', 'Querétaro', '{"Vinos de la Región Vitivinícola de Querétaro"}'::text[], 'MX', 20.843, -99.996, 62,
   'Wine country on the high plateau of central Mexico, with vineyards at about 1,900 metres or more. Best known for sparkling wine, it became the first protected wine geographical indication in Mexico in 2025.',
   null, null, null, null, 'Wine under the indication must be made only from Vitis vinifera grapes, and no sweeteners or flavourings may be used at any stage.',
   'https://dof.gob.mx/nota_detalle_popup.php?codigo=5751385', 'published'),
  ('wr_0147', 'Valle de Guadalupe', '{"Guadalupe Valley"}'::text[], 'MX', 32.066, -116.608, 30,
   'The main wine valley of Baja California, the state that makes most Mexican wine. Hot days, cool nights and the nearby ocean shape its wines, and salty water can leave a saline note.',
   null, null, null, null, null,
   'https://daily.sevenfifty.com/valle-de-guadalupes-groundbreaking-winemakers-are-passing-the-baton', 'published'),
  ('wr_0148', 'Yamanashi', '{"山梨","GI Yamanashi"}'::text[], 'JP', 35.602, 138.684, 38,
   'An inland basin ringed by mountains, sunny and dry by Japanese standards, with wide swings between day and night temperatures. Its signature grape is Koshu, which gives delicate white wines with citrus notes.',
   null, null, 2, 'Koshu with Japanese dishes based on seafood.', 'A wine labelled GI Yamanashi must be made only from listed grape varieties harvested in Yamanashi, then produced, stored and bottled in the prefecture, and confirmed by the GI control body.',
   'https://www.nta.go.jp/english/taxes/liquor_administration/02_01.htm', 'published'),
  ('wr_0149', 'Hokkaido', '{"北海道","GI Hokkaido"}'::text[], 'JP', 43.468, 143.326, 158,
   'Japan''s northernmost wine region and its coolest, with harsh winters. Among European grapes, Kerner leads for white wine and Zweigelt and Pinot Noir for red, and Yoichi has become known for its Pinot Noir.',
   null, null, null, null, 'A wine labelled GI Hokkaido must be made only from listed grape varieties harvested in Hokkaido, then produced, stored and bottled there, and confirmed by the GI control body.',
   'https://www.nta.go.jp/english/taxes/liquor_administration/02_07.htm', 'published'),
  ('wr_0150', 'Nagano', '{"長野","GI Nagano"}'::text[], 'JP', 36.115, 138.098, 66,
   'A mountainous prefecture where most vineyards sit above 500 metres. Cool nights keep acidity in the grapes and the climate is dry by Japanese standards. Merlot and Chardonnay lead among European grapes.',
   null, null, null, null, 'A wine labelled GI Nagano must be made only from listed grape varieties harvested in Nagano, then produced, stored and bottled in the prefecture, and confirmed by the GI control body. A stricter Nagano Wine Premium tier also exists.',
   'https://www.nta.go.jp/english/taxes/liquor_administration/02_16.htm', 'published'),
  ('wr_0151', 'Helan Mountain East Foothill', '{"贺兰山东麓","Ningxia","Eastern Foothills of Helan Mountain"}'::text[], 'CN', 38.615, 106.067, 30,
   'A dry, sunny region with a strongly continental climate on the eastern foothills of the Helan Mountains, in Ningxia. Winters are so cold that vines are buried each autumn, and Cabernet Sauvignon is the main grape.',
   null, null, null, null, 'Only producers granted permission may put the Helan Mountain East Foothill geographical indication mark or name on their labels; unauthorised use is prohibited.',
   'https://decanterchina.com/en/news/Decanter%20Features/ningxia-china-s-rapidly-emerging-fine-wine-region', 'published'),
  ('wr_0152', 'Württemberg', '{}'::text[], 'DE', 49.002, 9.082, 31,
   'Vineyards along the Neckar and its side valleys around Stuttgart and Heilbronn, many on steep slopes of Keuper marl and shell limestone. A traditional red wine region with about two thirds red vines, though Riesling is the most planted grape.',
   null, null, null, null, 'Labels show Qualitätswein or Prädikatswein, and every wine must pass an official test. Schillerwein, a pale red made from white and red grapes together, is a Württemberg term. From the 2026 vintage village and single vineyard names are reserved for estate bottlings, and from 2030 a dry wine may no longer carry a Prädikat.',
   'https://en.wikipedia.org/wiki/W%C3%BCrttemberg_(wine_region)', 'published'),
  ('wr_0153', 'Vulkanland Steiermark', '{"Südoststeiermark"}'::text[], 'AT', 47.094, 15.800, 37,
   'Hill vineyards in southeast Styria around extinct volcanoes, on basalt and tuff among other soils, where the dry Pannonian and humid Illyrian climates meet. The DAC is white only, and Klöch is known for Traminer.',
   null, null, null, null, 'Vulkanland Steiermark DAC is white only, from hand-picked grapes of eight varieties, at most 4 g/l sugar with Riesling and Traminer dry, and the vintage on the label. It has three levels: Gebietswein, Ortswein (nine areas, each with set lead varieties) and Riedenwein. Klöch Traminer may also be off dry or a Prädikatswein; reds are sold as Steiermark.',
   'https://info.bml.gv.at/dam/jcr:9bcf7647-c1cb-4809-aa5c-6d0ef56e3ed0/Vulkanland%20Steiermark_Produktspezifikation.pdf', 'published'),
  ('wr_0154', 'Badacsony', '{"Badacsonyi"}'::text[], 'HU', 46.853, 17.473, 9,
   'Basalt hills rising from the Tapolca Basin on the north shore of Lake Balaton, which tempers the climate. Mostly white wines, led by Olaszrizling and Pinot Gris, with rounded acidity and a salty, mineral note.',
   null, null, null, null, 'A grape named on the label must make up at least 85% of the wine. A white wine named after a hill, such as Szent György-hegy, must come entirely from that hill, and if it names a grape, entirely from that grape; it is aged at least six months, three of them in wood, and never sweetened.',
   'http://data.europa.eu/eli/C/2024/7443/oj', 'published'),
  ('wr_0155', 'Amyndeon', '{"Amynteo","Αμύνταιο"}'::text[], 'GR', 40.659, 21.663, 10,
   'A high plateau in Florina, northwest Greece, about 600 metres up, ringed by mountains and with lakes. Sandy soils have kept many old vines on their own roots. Only Xinomavro is used, for dry red, rosé and sparkling rosé.',
   null, null, null, null, 'Dry reds labelled Réserve need two years of ageing, at least 12 months in oak and 6 in bottle; Grande Réserve needs four years, at least 18 months in oak and 18 in bottle.',
   'https://webgate.ec.europa.eu/eambrosia-api/api/v1/attachments/11299', 'published'),
  ('wr_0156', 'Friuli Colli Orientali', '{"Colli Orientali del Friuli"}'::text[], 'IT', 46.079, 13.416, 13,
   'Hills east of Udine, sheltered by the Alps to the north, on layered marl and sandstone known locally as ponca. Whites from Friulano and Ribolla Gialla sit beside native reds such as Schioppettino and Refosco, and sweet Picolit.',
   null, null, null, 'Friulano with Prosciutto di San Daniele.', 'Riserva may be used two years after the harvest; for Pignolo only after four years, counted from 1 November of the harvest year. Pinot Bianco, Sauvignon and Pinot Nero may also be labelled Pinot Blanc, Sauvignon Blanc and Pinot Noir.',
   'https://winefolly.com/deep-dive/italian-white-wines-friuli-venezia-giulia/', 'published'),
  ('wr_0157', 'Colares', '{}'::text[], 'PT', 38.849, -9.423, 6,
   'A tiny appellation between the Sintra hills and the Atlantic, where vines grow ungrafted in deep sand that phylloxera could not cross. Ramisco reds have hard tannins and high acidity and need long ageing.',
   null, 4, 4, null, 'Reds must be at least 80% Ramisco and age 18 months in cask and 6 in bottle before sale; whites at least 80% Malvasia, with 6 months in cask and 3 in bottle.',
   'https://webgate.ec.europa.eu/eambrosia-api/api/v1/attachments/6924', 'published'),
  ('wr_0158', 'Alentejo', '{}'::text[], 'PT', 38.566, -7.904, 30,
   'Portugal''s broad southern plains, with a Mediterranean and continental climate of hot, dry summers. Reds are ripe and full bodied, often blends of Aragonez, Trincadeira and Alicante Bouschet, while Antão Vaz is the base of the whites.',
   null, null, null, null, 'A label may add the name of one of the eight sub-regions. Wine made in clay talha pots under the DO rules must say Vinho de Talha.',
   'https://webgate.ec.europa.eu/eambrosia-api/api/v1/attachments/1282', 'published'),
  ('wr_0159', 'Štajerska Slovenija', '{"Slovenska Štajerska"}'::text[], 'SI', 46.473, 16.190, 30,
   'Hill vineyards in northeast Slovenia toward the Pannonian plain, where white grapes fill over nine in ten vineyards. Laški rizling, Šipon and Sauvignon are mainstays, alongside late harvest sweet wines and a long sparkling tradition at Gornja Radgona.',
   null, null, null, null, 'A wine must score at least 16 points at an official tasting to carry the PDO. The name may be followed by a smaller unit, such as one of six sub-districts, and an estate name; sweet wines use the predikat terms pozna trgatev, izbor, jagodni izbor, suhi jagodni izbor and ledeno vino.',
   'https://webgate.ec.europa.eu/eambrosia-api/api/v1/attachments/10327', 'published');

insert into public.grapes
  (grape_code, name, aliases, colour, summary, tastes, aged_note,
   body, acidity, tannin, publication_status)
values
  ('gr_0105', 'Vidal Blanc', '{"Vidal"}'::text[], 'white',
   'A French hybrid of Ugni Blanc bred by Jean Louis Vidal in the 1930s. Winter hardy, with tough skins and good acidity, it is best known for Canadian Icewine.',
   '{"Pineapple","Grapefruit","Honeysuckle"}'::text[], null, 3, 4, null, 'published'),
  ('gr_0106', 'Koshu', '{"甲州"}'::text[], 'white',
   'A Japanese white grape with thick, pink skins, grown in Yamanashi for centuries. It gives light, delicate wines with citrus notes, often made to go with Japanese food.',
   '{"Citrus","Yuzu","White peach"}'::text[], null, 2, null, null, 'published'),
  ('gr_0107', 'Muscat Bailey A', '{"マスカット・ベーリーA"}'::text[], 'red',
   'A red grape bred in Japan in the 1920s by Zenbei Kawakami, from Bailey and Muscat Hamburg. Its wines are fruity, with strawberry aromas and soft tannins.',
   '{"Strawberry","Cherry candy"}'::text[], null, null, null, 2, 'published'),
  ('gr_0108', 'Kerner', '{}'::text[], 'white',
   'A white grape bred in Germany in 1929 by crossing the red Trollinger with Riesling. It gives fruity, aromatic wines in a style close to Riesling.',
   '{"Apple","Pear","Peach"}'::text[], null, null, null, null, 'published'),
  ('gr_0109', 'Marselan', '{}'::text[], 'red',
   'A red grape bred in France in 1961 from Cabernet Sauvignon and Grenache. It gives deeply coloured, fragrant wines and is now grown in China as well.',
   '{"Dark berries"}'::text[], null, null, null, 4, 'published'),
  ('gr_0110', 'Kéknyelű', '{}'::text[], 'white',
   'A rare white grape of Badacsony, on the north shore of Lake Balaton, grown almost nowhere else. Restrained, lightly aromatic dry whites with citrus, herbal and almond notes and a mineral edge.',
   '{"Citrus","Almond","Herbs","Blossom"}'::text[], 'Benefits from a few years in bottle.', null, null, null, 'published'),
  ('gr_0111', 'Schioppettino', '{"Ribolla Nera","Pocalza"}'::text[], 'red',
   'A red grape of Friuli and neighbouring Slovenia, at home around Prepotto in the Colli Orientali. Aromatic, medium bodied reds with pepper, raspberry and violet over high acidity.',
   '{"Pepper","Raspberry","Violet"}'::text[], null, 3, 4, null, 'published'),
  ('gr_0112', 'Picolit', '{}'::text[], 'white',
   'A rare white grape of Friuli whose poor fruit set gives very low yields. Used almost only for sweet wines from late picked or dried grapes, with soft floral aromas and peach and apricot.',
   '{"Apricot","Peach","Floral"}'::text[], null, null, null, null, 'published'),
  ('gr_0113', 'Malvasia de Colares', '{}'::text[], 'white',
   'A white grape of the Colares sands, genetically distinct from other Malvasias. Its wines are saline, with citrus and waxy notes.',
   '{"Citrus","Saline","Beeswax"}'::text[], null, null, null, null, 'published');

update public.grapes g set similar_grape_id = s.id, similar_note = 'One of its parents. Kerner is similar in style but a little more aromatic.' from public.grapes s where s.grape_code = 'gr_0008' and g.grape_code = 'gr_0108';

